/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type CalendarAppProps = Record<string, any>;

const CalendarApp: React.FC<CalendarAppProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#007AFF",
  textColor = "#111111",
  secondaryTextColor = "#8E8E93",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Calendar Data (2026: Feb has 28 days, March has 31. Both start on Sunday)
  const monthsData = [
    { name: "February", year: "2026", startDay: 0, days: 28, rows: 4 }, // Starts Sunday, exactly 4 weeks
    { name: "March", year: "2026", startDay: 0, days: 31, rows: 5 },    // Starts Sunday, 5 weeks
  ];
  const daysOfWeek = ["S", "M", "T", "W", "T", "F", "S"];

  // Layout Dimensions
  const paddingX = 60;
  const usableW = width - paddingX * 2;
  const cellW = usableW / 7;
  const cellH = 160;
  const headerH = 140;
  const daysRowH = 80;
  const monthGap = 80; // Gap between months for natural scrolling

  // Calculate dynamic heights and top positions for each month
  let currentTop = 0;
  const months = monthsData.map((m) => {
    const h = headerH + daysRowH + m.rows * cellH + monthGap;
    const layout = { ...m, top: currentTop, height: h };
    currentTop += h;
    return layout;
  });

  // Animation Timings
  const startAnimFrame = 30; // 1 second pause at start
  const endAnimFrame = fps * durationInSeconds - 30; // 1 second pause at end
  const animDuration = endAnimFrame - startAnimFrame;

  // Progress 1 to 59 (Total days across Feb 2026 + Mar 2026)
  const totalDays = 28 + 31;
  const dayProgress = interpolate(frame, [startAnimFrame, endAnimFrame], [1, totalDays], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const currentActiveDay = Math.floor(dayProgress);

  // Determine which month and day is currently active
  let activeMonthIdx = 0;
  let activeDayNum = 1;
  if (currentActiveDay <= 28) {
    activeMonthIdx = 0;
    activeDayNum = currentActiveDay;
  } else {
    activeMonthIdx = 1;
    activeDayNum = currentActiveDay - 28;
  }

  // Scroll logic: transition smoothly when crossing from Feb 28 to March 1
  // Day 28 is reached at progress 28, which is 27 units out of 58 total units
  const scrollMid = startAnimFrame + (27 / 58) * animDuration;
  const scrollStart = Math.max(0, scrollMid - 20);
  const scrollEnd = Math.min(fps * durationInSeconds, scrollMid + 20);

  const scrollTarget = -months[1].top; // Scroll to put March at the top

  const scrollY = interpolate(
    frame,
    [scrollStart, scrollEnd],
    [0, scrollTarget],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.cubic),
    }
  );

  // Slight motion blur during the fast vertical swipe
  const blurAmount = interpolate(
    frame,
    [scrollStart, scrollMid, scrollEnd],
    [0, 6, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.ease),
    }
  );

  // Camera Zoom & Parallax effect
  const containerScale = interpolate(frame, [0, fps * durationInSeconds], [1, 1.05]);
  const containerTranslateY = interpolate(frame, [0, fps * durationInSeconds], [0, 24]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, transition: "none" }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          transform: `scale(${containerScale}) translateY(${containerTranslateY}px)`,
          transformOrigin: "center center",
          display: "flex",
          flexDirection: "column",
          transition: "none",
        }}
      >
        {/* Fixed Top Status Bar (iOS Style Mock) */}
        <div
          style={{
            height: 120,
            width: "100%",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            padding: "0 60px",
            paddingTop: 40,
            zIndex: 10,
            background: `linear-gradient(to bottom, ${backgroundColor} 60%, ${backgroundColor}00 100%)`,
          }}
        >
          <span style={{ fontSize: 34, fontWeight: 600, color: textColor, letterSpacing: "-0.02em" }}>
            9:41
          </span>
          {/* Dynamic Island Mock */}
          <div
            style={{
              position: "absolute",
              left: "50%",
              transform: "translateX(-50%)",
              width: 140,
              height: 36,
              backgroundColor: textColor,
              borderRadius: 20,
              opacity: 0.9,
            }}
          />
          <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
            <div style={{ width: 34, height: 22, backgroundColor: textColor, opacity: 0.2, borderRadius: 4 }} />
            <div style={{ width: 44, height: 22, backgroundColor: textColor, opacity: 0.8, borderRadius: 6 }} />
          </div>
        </div>

        {/* Scrolling Calendar Content */}
        <div
          style={{
            position: "absolute",
            top: 140, // Below top bar
            left: 0,
            width: "100%",
            transform: `translateY(${scrollY}px)`,
            filter: `blur(${blurAmount}px)`,
            transition: "none",
          }}
        >
          {months.map((month, mIdx) => {
            const totalCells = month.rows * 7;
            const cells = Array.from({ length: totalCells }).map((_, i) => {
              const dayNum = i - month.startDay + 1;
              const isValidDay = dayNum >= 1 && dayNum <= month.days;
              return { dayNum, isValidDay, index: i };
            });

            return (
              <div
                key={month.name}
                style={{
                  position: "absolute",
                  top: month.top,
                  left: 0,
                  width: "100%",
                  padding: `0 ${paddingX}px`,
                }}
              >
                {/* Month Header */}
                <div
                  style={{
                    height: headerH,
                    display: "flex",
                    alignItems: "flex-end",
                    paddingBottom: 20,
                  }}
                >
                  <span style={{ fontSize: 84, fontWeight: 700, color: textColor, letterSpacing: "-0.03em" }}>
                    {month.name}{" "}
                    <span style={{ color: secondaryTextColor, fontWeight: 500 }}>
                      {month.year}
                    </span>
                  </span>
                </div>

                {/* Days of Week Row */}
                <div style={{ display: "flex", height: daysRowH, alignItems: "center" }}>
                  {daysOfWeek.map((d, i) => (
                    <div
                      key={i}
                      style={{
                        width: cellW,
                        textAlign: "center",
                        fontSize: 32,
                        fontWeight: 600,
                        color: secondaryTextColor,
                      }}
                    >
                      {d}
                    </div>
                  ))}
                </div>

                {/* Days Grid */}
                <div style={{ display: "flex", flexWrap: "wrap", width: usableW }}>
                  {cells.map((cell) => {
                    const isSelected =
                      mIdx === activeMonthIdx &&
                      cell.isValidDay &&
                      cell.dayNum === activeDayNum;

                    return (
                      <div
                        key={cell.index}
                        style={{
                          width: cellW,
                          height: cellH,
                          display: "flex",
                          justifyContent: "center",
                          alignItems: "center",
                          position: "relative",
                          borderTop: `1px solid ${secondaryTextColor}20`, // Thin grid line horizontal
                          borderRight: (cell.index + 1) % 7 !== 0 ? `1px solid ${secondaryTextColor}20` : undefined, // Thin grid line vertical
                        }}
                      >
                        {isSelected && (
                          <div
                            style={{
                              position: "absolute",
                              width: 90,
                              height: 90,
                              borderRadius: 45,
                              backgroundColor: primaryColor,
                              boxShadow: `0 8px 24px ${primaryColor}55`, // Subtle soft shadow
                            }}
                          />
                        )}
                        {cell.isValidDay && (
                          <span
                            style={{
                              position: "relative",
                              zIndex: 1,
                              fontSize: 44,
                              fontWeight: isSelected ? 600 : 400,
                              color: isSelected ? "#FFFFFF" : textColor,
                            }}
                          >
                            {cell.dayNum}
                          </span>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
        
        {/* Soft bottom fade to simulate UI edge */}
        <div style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          right: 0,
          height: 120,
          background: `linear-gradient(to top, ${backgroundColor} 30%, ${backgroundColor}00 100%)`,
          zIndex: 10
        }} />
        
        {/* Home Indicator */}
        <div style={{
          position: "absolute",
          bottom: 24,
          left: "50%",
          transform: "translateX(-50%)",
          width: 300,
          height: 10,
          backgroundColor: textColor,
          opacity: 0.8,
          borderRadius: 10,
          zIndex: 11
        }} />
      </div>
    </AbsoluteFill>
  );
};

export default CalendarApp;